for u in ftp://ftp.gfz-potsdam.de/pub/GNSS/products/mgex/ ftp://ftp.aiub.unibe.ch/CODE_MGEX/CODE/ ftp://igs.ign.fr/pub/igs/products/mgex/ https://isdc-data.gfz.de/gnss/products/rapid/ https://cddis.nasa.gov/archive/gnss/products/mgex/; do echo "== $u"; curl -s -m 40 --list-only "$u" 2>&1 | head -5 | tr '\n' ' '; echo; done
w=2300; for u in ftp://ftp.gfz-potsdam.de/pub/GNSS/products/mgex/$w/ ftp://igs.ign.fr/pub/igs/products/mgex/$w/ ftp://ftp.aiub.unibe.ch/CODE_MGEX/CODE/2024/; do echo "== $u"; curl -s -m 40 --list-only "$u" 2>&1 | grep -i 'sp3\|SP3' | head -4 | tr '\n' ' '; echo; done
